import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from groupedBar ----
// US Census American Community Survey population by age, for the six most
// populous states. Ages are grouped into five bands.
const AGE_GROUPS = ['Under 20', '20 to 39', '40 to 59', '60 to 79', '80 and over'];

type StatePopulationRow = { state: string; age: string; population: number };

const RAW: Record<string, number[]> = {
  California: [10208774, 11163567, 10221352, 5749139, 1311374],
  Texas: [7893619, 7716981, 6890676, 3722980, 732179],
  Florida: [4542114, 5014006, 5338559, 4020206, 1019566],
  'New York': [4765536, 5499621, 5372947, 3255262, 804091],
  Illinois: [3335666, 3511693, 3470435, 2054942, 478948],
  Pennsylvania: [3066949, 3232857, 3526669, 2342433, 615069]
};

const STATES = Object.keys(RAW);

const groupedBarPopulation: StatePopulationRow[] = Object.entries(RAW).flatMap(
  ([state, values]) => AGE_GROUPS.map((age, i) => ({ state, age, population: values[i] }))
);

const MARGIN = { top: 34, right: 16, bottom: 30, left: 56 };
const LEGEND_SWATCH = 11;
const MIN_LEGEND_ITEM = 88;

const formatTick = d3.format('~s');

/** One value per group per series, plus the two orderings the outer and inner band scales follow. */
export type Data = {
  rows: { state: string; age: string; population: number }[];
  states: string[];
  ages: string[];
};

const DEMO: Data = { rows: groupedBarPopulation, states: STATES, ages: AGE_GROUPS };

export default function GroupedBarChart({ data = DEMO, width }:
  { data?: Data; width: number }) {
  const height = Math.round(width * 0.55);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const byState = useMemo(() => d3.group(data.rows, (d) => d.state), [data]);

  // fx groups by state; x nests each age band within the group's own band.
  const fx = useMemo(
    () =>
      d3
        .scaleBand<string>()
        .domain(data.states)
        .range([0, Math.max(innerWidth, 0)])
        .paddingInner(0.15),
    [data, innerWidth]
  );

  const x = useMemo(
    () => d3.scaleBand<string>().domain(data.ages).range([0, fx.bandwidth()]).padding(0.06),
    [data, fx]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([0, d3.max(data.rows, (d) => d.population) ?? 0])
        .nice()
        .range([Math.max(innerHeight, 0), 0]),
    [data, innerHeight]
  );

  const color = useMemo(
    () =>
      d3
        .scaleOrdinal<string, string>()
        .domain(data.ages)
        .range(d3.schemeSpectral[data.ages.length]),
    [data]
  );

  const stateTicks: Tick[] = useMemo(
    () =>
      data.states.map((state) => ({
        value: state,
        offset: (fx(state) ?? 0) + fx.bandwidth() / 2
      })),
    [data, fx]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(6).map((v) => ({ value: formatTick(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  const legendStep = innerWidth / data.ages.length;
  const showLegend = legendStep >= MIN_LEGEND_ITEM;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={
        'Grouped bar chart of United States population by age band for the six most populous ' +
        'states. Each state groups five age bands side by side, from under 20 to 80 and over.'
      }
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />

        {data.states.map((state) => (
          <g key={state} transform={`translate(${fx(state)},0)`}>
            {(byState.get(state) ?? []).map((d) => (
              <rect
                key={d.age}
                x={x(d.age)}
                y={y(d.population)}
                width={x.bandwidth()}
                height={Math.max(innerHeight - y(d.population), 0)}
                fill={color(d.age)}
              >
                <title>{`${state} · ${d.age}: ${d.population.toLocaleString('en')}`}</title>
              </rect>
            ))}
          </g>
        ))}

        <AxisBottom ticks={stateTicks} height={innerHeight} width={innerWidth} />

        {showLegend && (
          <g transform="translate(0,-22)">
            {data.ages.map((group, i) => (
              <g key={group} transform={`translate(${i * legendStep},0)`}>
                <rect width={LEGEND_SWATCH} height={LEGEND_SWATCH} fill={color(group)} />
                <text x={LEGEND_SWATCH + 5} y={LEGEND_SWATCH - 1} fontSize={11} fill="var(--text)">
                  {group}
                </text>
              </g>
            ))}
          </g>
        )}
      </g>
    </svg>
  );
}
